/// Enumeration for the various error codes an API can return.
///
/// **Since Tizen:**
/// - 2.3
/// @nodoc
abstract class data_control_error_e {
  /// < Successful
  static const int DATA_CONTROL_ERROR_NONE = 0;

  /// < Out of memory
  static const int DATA_CONTROL_ERROR_OUT_OF_MEMORY = -12;

  /// < I/O error
  static const int DATA_CONTROL_ERROR_IO_ERROR = -5;

  /// < Invalid parameter
  static const int DATA_CONTROL_ERROR_INVALID_PARAMETER = -22;

  /// < Permission denied
  static const int DATA_CONTROL_ERROR_PERMISSION_DENIED = -13;

  /// < Too long argument
  static const int DATA_CONTROL_ERROR_MAX_EXCEEDED = -18415615;
}
